WH.Gatherer.addData(6, 8, {"48979":{"name_enus":"Butchery","icon":"inv_axe_68","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Whenever you kill an enemy that grants experience or honor, you generate up to 10 runic power.  In addition, you generate 1 runic power per 5 sec while in combat."},"48997":{"name_enus":"Subversion","icon":"spell_deathknight_subversion","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance of Blood Strike, Scourge Strike, Heart Strike and Obliterate by 3%, and reduces threat generated while in Blood or Unholy Presence by 8%."},"49182":{"name_enus":"Blade Barrier","icon":"ability_upgrademoonglaive","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Whenever your Blood Runes are on cooldown, you gain the Blade Barrier effect, which decreases damage taken by 1% for the next 10 sec."},"48978":{"name_enus":"Bladed Armor","icon":"inv_shoulder_36","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your attack power by 1 for every 180 armor value you have."},"49004":{"name_enus":"Scent of Blood","icon":"ability_rogue_bloodyeye","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You have a 15% chance after dodging, parrying or taking  direct damage to gain the Scent of Blood effect, causing your next melee hit to generate 10 runic power."},"55107":{"name_enus":"Two-Handed Weapon Specialization","icon":"inv_sword_68","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage you deal with two-handed melee weapons by 2%."},"48982":{"name_enus":"Rune Tap","icon":"spell_deathknight_runetap","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Converts 1 Blood Rune into 10% of your maximum health."},"48987":{"name_enus":"Dark Conviction","icon":"spell_deathknight_darkconviction","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your chance to critically hit with weapons, spells and abilities by 1%."},"49467":{"name_enus":"Death Rune Mastery","icon":"inv_sword_62","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Whenever you hit with Death Strike or Obliterate there is a 33% chance that the Frost and Unholy Runes will become Death Runes when they activate.  Death Runes count as a Blood, Frost or Unholy Rune."},"48985":{"name_enus":"Improved Rune Tap","icon":"spell_deathknight_runetap","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the health provided by Rune Tap by 33% and lowers its cooldown by 10 sec."},"49145":{"name_enus":"Spell Deflection","icon":"spell_deathknight_spelldeflection","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You have a chance equal to your Parry chance of taking 15% less damage from a direct damage spell."},"49015":{"name_enus":"Vendetta","icon":"spell_deathknight_vendetta","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Heals you for up to 2% of your maximum health whenever you kill a target that yields experience or honor."},"48977":{"name_enus":"Bloody Strikes","icon":"spell_deathknight_deathstrike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage of Blood Strike by 5% and Heart Strike by 15%, and increases the damage of Blood Boil by 10%."},"49006":{"name_enus":"Veteran of the Third War","icon":"spell_misc_warsongfocus","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your total Strength by 2%, your Stamina by 1%, and your expertise by 2."},"49005":{"name_enus":"Mark of Blood","icon":"ability_hunter_rapidkilling","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Place a Mark of Blood on an enemy.  Whenever the marked enemy deals damage to a target, that target is healed for 4% of its maximum health.  Lasts for 20 sec or up to 20 hits."},"48988":{"name_enus":"Bloody Vengeance","icon":"ability_backstab","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives you a 1% bonus to physical damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability.  This effect stacks up to 3 times."},"53137":{"name_enus":"Abomination's Might","icon":"ability_warrior_intensifyrage","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the attack power by 5% of party and raid members within 100 yards.  Also increases your total Strength by 1%."},"49027":{"name_enus":"Bloodworms","icon":"spell_shadow_soulleech","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your weapon hits have a 3% chance to cause the target to spawn 2-4 Bloodworms.  Bloodworms attack your enemies, healing you as they do damage for 20 sec or until killed."},"49016":{"name_enus":"Unholy Frenzy","icon":"spell_deathknight_bladedarmor","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Induces a friendly unit into a killing frenzy for 30 sec.  The target is Enraged, which increases their physical damage by 20%, but causes them to lose health equal to 1% of their maximum health every second."},"50365":{"name_enus":"Improved Blood Presence","icon":"spell_deathknight_bloodpresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"While in Frost Presence or Unholy Presence, you retain 2% healing from Blood Presence, and healing done to you is increased by 5% in Blood Presence."},"62905":{"name_enus":"Improved Death Strike","icon":"spell_deathknight_butcher2","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage of your Death Strike by 15%, increases its critical strike chance by 3%, and increases the healing granted by 25%."},"49018":{"name_enus":"Sudden Doom","icon":"spell_shadow_painspike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Blood Strikes and Heart Strikes have a 5% chance to launch a free Death Coil at your target."},"55233":{"name_enus":"Vampiric Blood","icon":"spell_shadow_lifedrain","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Temporarily grants the Death Knight 15% of maximum health and increases the amount of health generated through spells and effects by 35% for 10 sec.  After the effect expires, the health is lost."},"49189":{"name_enus":"Will of the Necropolis","icon":"ability_creature_cursed_02","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Damage that would take you below 35% health or taken while you are at 35% health is reduced by 5%."},"55050":{"name_enus":"Heart Strike","icon":"inv_weapon_shortblade_40","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Instantly strike the target and his nearest ally, causing 50% weapon damage plus 125 on the primary target, and 25% weapon damage plus 63 on the secondary target.  Each target takes 10% additional damage for each of your diseases active on that target<br /><br /><span class='q2'>Glyph of Heart Strike</span><br /><span class='q9'> and movement speed is reduced by by 50% for 10 sec</span><br /><br />."},"49023":{"name_enus":"Might of Mograine","icon":"spell_deathknight_classicon","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike damage bonus of your Blood Boil, Blood Strike, Death Strike, and Heart Strike abilities by 15%."},"61154":{"name_enus":"Blood Gorged","icon":"spell_nature_reincarnation","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When you are above 75% health, you deal 2% more damage.  In addition, your attacks ignore up to 2% of your opponent's armor at all times."},"49028":{"name_enus":"Dancing Rune Weapon","icon":"inv_sword_07","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Summons a second rune weapon that fights on its own for 12 sec, doing the same attacks as the Death Knight but for 50% reduced damage and healing."},"49175":{"name_enus":"Improved Icy Touch","icon":"spell_deathknight_icetouch","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Icy Touch does an additional 5% damage and your Frost Fever reduces melee and ranged attack speed by an additional 2%."},"49455":{"name_enus":"Runic Power Mastery","icon":"spell_arcane_arcane01","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your maximum Runic Power by 15."},"49042":{"name_enus":"Toughness","icon":"spell_holy_devotion","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your armor value from items by 2% and reduces the duration of all movement slowing effects by 6%."},"55061":{"name_enus":"Icy Reach","icon":"spell_frost_manarecharge","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the range of your Icy Touch,  Chains of Ice and Howling Blast by 5 yards."},"49140":{"name_enus":"Black Ice","icon":"spell_shadow_darkritual","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your Frost and Shadow damage by 2%."},"49226":{"name_enus":"Nerves of Cold Steel","icon":"ability_dualwield","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your chance to hit with one-handed melee weapons by 1% and increases the damage done by your offhand weapon by 8%."},"50880":{"name_enus":"Icy Talons","icon":"spell_deathknight_icytalons","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You leech heat from victims of your Frost Fever, so that when their melee attack speed is reduced, yours increases by 4% for the next 20 sec."},"49039":{"name_enus":"Lichborne","icon":"spell_shadow_raisedead","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Draw upon unholy energy to become undead for 10 sec.  While undead, you are immune to Charm, Fear and Sleep effects."},"51468":{"name_enus":"Annihilation","icon":"inv_weapon_hand_18","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance of your melee special abilities by 1%.  In addition, there is a 33% chance that your Obliterate will do its damage without consuming diseases."},"51123":{"name_enus":"Killing Machine","icon":"inv_sword_122","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your melee attacks have a chance to make your next Icy Touch, Howling Blast or Frost Strike a critical strike."},"49149":{"name_enus":"Chill of the Grave","icon":"spell_frost_frostshock","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Chains of Ice, Howling Blast, Icy Touch and Obliterate generate 2.5 additional runic power."},"49137":{"name_enus":"Endless Winter","icon":"spell_shadow_twilight","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your strength is increased by 2% and the cost of your Mind Freeze is reduced to 10 runic power."},"49186":{"name_enus":"Frigid Dreadplate","icon":"inv_chest_mail_04","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the chance melee attacks will hit you by 1%."},"49471":{"name_enus":"Glacier Rot","icon":"spell_nature_removedisease","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Diseased enemies take 7% more damage from your Icy Touch, Howling Blast and Frost Strike."},"49796":{"name_enus":"Deathchill","icon":"spell_shadow_soulleech_2","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When activated, makes your next Icy Touch, Howling Blast, Frost Strike or Obliterate a critical hit if used within 30 sec."},"55610":{"name_enus":"Improved Icy Talons","icon":"spell_deathknight_icytalons","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases the melee haste of all party and raid members within 100 yds by 20% and your haste by an additional 5%."},"49024":{"name_enus":"Merciless Combat","icon":"inv_sword_112","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Icy Touch, Howling Blast, Obliterate and Frost Strike do an additional 6% damage when striking targets with less than 35% health."},"49188":{"name_enus":"Rime","icon":"spell_frost_freezingbreath","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance of your Icy Touch and Obliterate by 5% and casting Obliterate has a 5% chance to reset the cooldown on Howling Blast and cause your next Howling Blast to consume no runes."},"50040":{"name_enus":"Chilblains","icon":"spell_frost_wisp","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Victims of your Frost Fever disease are Chilled, reducing movement speed by 15% for 10 sec."},"49203":{"name_enus":"Hungering Cold","icon":"inv_staff_15","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Purges the earth around the Death Knight of all heat.  Enemies within 10 yards are trapped in ice, preventing them from performing any action for 10 sec and infecting them with Frost Fever.  Enemies are considered Frozen, but any damage other than diseases will break the ice."},"50384":{"name_enus":"Improved Frost Presence","icon":"spell_deathknight_frostpresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"While in Blood Presence or Unholy Presence, you retain 4% stamina from Frost Presence, and damage done to you is decreased by an additional 1% in Frost Presence."},"65661":{"name_enus":"Threat of Thassarian","icon":"ability_dualwieldspecialization","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When dual-wielding, your Death Strikes, Obliterates, Plague Strikes, Rune Strikes, Blood Strikes and Frost Strikes have a 30% chance to also deal damage with your offhand weapon."},"54639":{"name_enus":"Blood of the North","icon":"inv_weapon_shortblade_79","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases Blood Strike and Frost Strike damage by 3%.  In addition, whenever you hit with Blood Strike or Pestilence there is a 30% chance that the Blood Rune will become a Death Rune when it activates.  Death Runes count as a Blood, Frost or Unholy Rune."},"51271":{"name_enus":"Unbreakable Armor","icon":"inv_armor_helm_plate_naxxramas_raidwarrior_c_01","screenshot":{"id":1073106,"imageType":2},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Reinforces your armor with a thick coat of ice, increasing your armor by 25% and increasing your Strength by 20% for 20 sec."},"49200":{"name_enus":"Acclimation","icon":"classic_spell_fire_elementaldevastation","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When you are hit by a spell, you have a 10% chance to boost your resistance to that type of magic for 18 sec.  Stacks up to 3 times."},"49143":{"name_enus":"Frost Strike","icon":"spell_deathknight_empowerruneblade2","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Instantly strike the enemy, causing 55% weapon damage plus 48 as Frost damage."},"50187":{"name_enus":"Guile of Gorefiend","icon":"inv-sword_53","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike damage bonus of your Blood Strike, Frost Strike, Howling Blast and Obliterate abilities by 15%, and increases the duration of your Icebound Fortitude by 2 secs."},"49202":{"name_enus":"Tundra Stalker","icon":"spell_nature_tranquility","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your spells and abilities deal 3% more damage to targets infected with Frost Fever.  Also increases your expertise by 1."},"49184":{"name_enus":"Howling Blast","icon":"spell_frost_arcticwinds","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Blast the target with a frigid wind dealing 198 to 214 Frost damage to all enemies within 10 yards."},"51745":{"name_enus":"Vicious Strikes","icon":"spell_deathknight_plaguestrike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance by 3% and critical strike damage bonus by 15% of your Plague Strike and Scourge Strike."},"48962":{"name_enus":"Virulence","icon":"spell_shadow_burningspirit","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your chance to hit with your spells by 1% and reduces the chance that your damage over time diseases can be cured by 10%."},"55129":{"name_enus":"Anticipation","icon":"spell_nature_mirrorimage","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your Dodge chance by 1%."},"49036":{"name_enus":"Epidemic","icon":"spell_shadow_shadowwordpain","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the duration of Blood Plague and Frost Fever by 3 sec."},"48963":{"name_enus":"Morbidity","icon":"spell_shadow_deathanddecay","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage and healing of Death Coil by 5% and reduces the cooldown on Death and Decay by 5 sec."},"49588":{"name_enus":"Unholy Command","icon":"spell_deathknight_strangulate","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown of your Death Grip ability by 5 sec."},"48965":{"name_enus":"Ravenous Dead","icon":"spell_deathknight_gnaw_ghoul","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your total Strength by 1% and the contribution your Ghouls get from your Strength and Stamina by 20%."},"49013":{"name_enus":"Outbreak","icon":"spell_shadow_plaguecloud","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage of Plague Strike by 10% and Scourge Strike by 7%."},"51459":{"name_enus":"Necrosis","icon":"inv_weapon_shortblade_60","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your auto attacks deal an additional 4% Shadow damage."},"49158":{"name_enus":"Corpse Explosion","icon":"ability_creature_disease_02","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Cause a corpse or your ghoul to explode for 166 Shadow damage to all enemies within 10 yards.  Will use a nearby corpse if the target is not a corpse.  Does not affect mechanical or elemental corpses."},"49146":{"name_enus":"On a Pale Horse","icon":"spell_deathknight_summondeathcharger","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You become as hard to stop as death itself.  The duration of all Stun and Fear effects used against you is reduced by 10%, and your mounted speed is increased by 10%.  This does not stack with other movement speed increasing effects."},"49219":{"name_enus":"Blood-Caked Blade","icon":"ability_criticalstrike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your auto attacks have a 10% chance to cause a Blood-Caked Strike, which hits for 25% weapon damage plus 12.5% for each of your diseases on the target."},"55620":{"name_enus":"Night of the Dead","icon":"spell_deathknight_armyofthedead","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown on Raise Dead by 45 sec and the cooldown on Army of the Dead by 2 min.  Also reduces the damage your pet takes from creature area of effect attacks by 45%."},"49194":{"name_enus":"Unholy Blight","icon":"spell_shadow_contagion","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Causes the victims of your Death Coil to be surrounded by a vile swarm of unholy insects, taking 10% of the damage done by the Death Coil over 10 sec, and preventing any diseases on the victim from being dispelled."},"49220":{"name_enus":"Impurity","icon":"spell_shadow_shadowandflame","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"The attack power bonus of your spells is increased by 4%."},"49223":{"name_enus":"Dirge","icon":"spell_shadow_shadesofdarkness","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Death Strike, Plague Strike and Scourge Strike generate 2.5 additional runic power."},"55666":{"name_enus":"Desecration","icon":"spell_shadow_shadowfiend","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Plague Strikes and Scourge Strikes cause the Desecrated Ground effect.  Targets in the area are slowed by 25% by the grasping arms of the dead while standing on the unholy ground.  Lasts 20 sec."},"49224":{"name_enus":"Magic Suppression","icon":"spell_shadow_antimagicshell","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You take 2% less damage from all magic.  In addition, your Anti-Magic Shell absorbs an additional 8% of spell damage."},"49208":{"name_enus":"Reaping","icon":"spell_shadow_shadetruesight","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Whenever you hit with Blood Strike or Pestilence there is a 33% chance that the Blood Rune becomes a Death Rune when it activates.  Death Runes count as a Blood, Frost or Unholy Rune."},"52143":{"name_enus":"Master of Ghouls","icon":"spell_shadow_animatedead","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Reduces the cooldown on Raise Dead by 60 sec, and the Ghoul summoned by your Raise Dead spell is considered a pet under your control.  Unlike normal Death Knight Ghouls, your pet does not have a limited duration."},"66799":{"name_enus":"Desolation","icon":"spell_shadow_unholyfrenzy","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Blood Strikes cause you to deal 1% additional damage with all attacks for the next 20 sec."},"51052":{"name_enus":"Anti-Magic Zone","icon":"spell_deathknight_antimagiczone","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Places a large, stationary Anti-Magic Zone that reduces spell damage done to party or raid members inside it by 75%.  The Anti-Magic Zone lasts for 10 sec or until it absorbs (10000 + 2 * Attack power) spell damage."},"50391":{"name_enus":"Improved Unholy Presence","icon":"spell_deathknight_unholypresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"While in Blood Presence or Frost Presence, you retain 8% increased movement speed from Unholy Presence, and your runes finish their cooldowns 5% faster in Unholy Presence."},"63560":{"name_enus":"Ghoul Frenzy","icon":"ability_ghoulfrenzy","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Grants your pet 25% haste for 30 sec and  heals it for 60% of its health over the duration."},"49032":{"name_enus":"Crypt Fever","icon":"spell_nature_nullifydisease","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your diseases also cause Crypt Fever, which increases disease damage taken by the target by 10%."},"49222":{"name_enus":"Bone Shield","icon":"inv_chest_leather_13","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"The Death Knight is surrounded by 3 whirling bones.  While at least 1 bone remains, <dfn title=\"she\">he</dfn> takes 20% less damage from all sources and deals 2% more damage with all attacks, spells and abilities.  Each damaging attack that lands consumes 1 bone.  Lasts 5 min."},"49217":{"name_enus":"Wandering Plague","icon":"spell_shadow_callofbone","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When your diseases damage an enemy, there is a chance equal to your melee critical strike chance that they will cause 33% additional damage to the target and all enemies within 8 yards.  Ignores any target under the effect of a spell that is cancelled by taking damage."},"51099":{"name_enus":"Ebon Plaguebringer","icon":"ability_creature_cursed_03","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Crypt Fever morphs into Ebon Plague, which increases magic damage taken by 4% in addition to increasing disease damage taken.  Improves your critical strike chance with weapons and spells by 1% at all times."},"55090":{"name_enus":"Scourge Strike","icon":"spell_deathknight_scourgestrike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"An unholy strike that deals 70% of weapon damage as Physical damage plus 238.  In addition, for each of your diseases on your target, you deal an additional 12% of the Physical damage done as Shadow damage."},"50117":{"name_enus":"Rage of Rivendare","icon":"inv_weapon_halberd14","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your spells and abilities deal 2% more damage to targets infected with Blood Plague.  Also increases your expertise by 1."},"49206":{"name_enus":"Summon Gargoyle","icon":"ability_hunter_pet_bat","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"A Gargoyle flies into the area and bombards the target with Nature damage modified by the Death Knight's attack power.  Persists for 30 sec."}});
